package com.istqb.prep.data

import android.content.Context
import android.content.SharedPreferences

class IstqbRepository(context: Context) {
    private val prefs: SharedPreferences =
        context.getSharedPreferences("istqb_prep_stats_v1", Context.MODE_PRIVATE)

    fun loadEInkFontSize(): Int {
        return prefs.getInt("eink_font_size", 18)
            .coerceIn(14, 24)
    }

    fun saveEInkFontSize(size: Int) {
        prefs.edit()
            .putInt("eink_font_size", size.coerceIn(14, 24))
            .apply()
    }


    fun loadDatabase(lang: String = "RU"): SyllabusDatabase {
        val normalizedLang = lang.trim().uppercase()
        val allModules = buildSyllabusModules() + buildSyllabusModulesRu()

        val filteredModules = allModules.filter { module ->
            module.language.equals(normalizedLang, ignoreCase = true)
        }.ifEmpty {
            when (normalizedLang) {
                "RU" -> allModules.filter { it.language.equals("EN", ignoreCase = true) }
                else -> allModules
            }
        }

        // All questions are always available. In RU mode a Russian version is used when it exists,
        // otherwise the English question with the same id is shown.
        val enQuestions = buildSyllabusQuestions()
        val ruById = buildSyllabusQuestionsRu().associateBy { it.id }
        val filteredQuestions = when (normalizedLang) {
            "RU" -> enQuestions.map { ruById[it.id] ?: it }
            else -> enQuestions
        }
        return SyllabusDatabase(
            version = "CTFL v4.0.1 (2024-09-15)",
            modules = filteredModules,
            questions = filteredQuestions
        )
    }

    fun getCorrectIds(): Set<String> {
        return prefs.getStringSet("correct_ids", emptySet())?.toSet() ?: emptySet()
    }

    fun getWrongIds(): Set<String> {
        return prefs.getStringSet("wrong_ids", emptySet())?.toSet() ?: emptySet()
    }

    fun recordAnswer(questionId: Int, isCorrect: Boolean) {
        val key = questionId.toString()
        val correct = getCorrectIds().toMutableSet()
        val wrong = getWrongIds().toMutableSet()

        if (isCorrect) {
            correct.add(key)
            wrong.remove(key)
        } else {
            wrong.add(key)
            correct.remove(key)
        }

        prefs.edit()
            .putStringSet("correct_ids", correct)
            .putStringSet("wrong_ids", wrong)
            .apply()
    }

    fun clearStats() {
        prefs.edit()
            .remove("correct_ids")
            .remove("wrong_ids")
            .apply()
    }

